const storyContext = $fromAI('story_context', 'Description narrative de la séquence');
const sequence = $fromAI('sequence', 'S1|S2|S3|S4|S5', 'S1');
const cameraAction = $fromAI('camera_action', 'dolly|static|closeup|slowmo|reveal', 'static');
const emotion = $fromAI('emotion', 'attente|approche|contemplation|fermeture|eveil', 'attente');

const sceneFrames = { S1: {start:1, end:240}, S2: {start:241, end:960}, S3: {start:961, end:1440}, S4: {start:1441, end:1920}, S5: {start:1921, end:2280} };
const frames = sceneFrames[sequence] || sceneFrames.S1;

return {
  tool: 'blender_story',
  sequence: sequence,
  frames: frames,
  camera: cameraAction,
  emotion: emotion,
  narrative: storyContext,
  render: { engine:'CYCLES', device:'GPU', resolutionX:3840, resolutionY:2160, fps:24, samples:512 },
  palette: {
    skinAlbedo: '(0.420,0.239,0.180)',
    goldSacre: '(0.788,0.588,0.227)',
    shuka: '(0.753,0.224,0.169)'
  },
  instruction: `Génère un script Python pour Blender 5.0 basé sur l'histoire suivante : ${storyContext}. Séquence ${sequence}, action caméra ${cameraAction}, émotion ${emotion}. Inclure les imports, la configuration de la scène, l'animation caméra, et éventuellement des particules d'or.`
};

const narrative = $fromAI('story_context', 'Description narrative pour UE5');
const vfxType = $fromAI('vfx_type', 'particles_or|aura_shader|oudjat_beam|cloth_wind', 'particles_or');
const metahumanEmotion = $fromAI('metahuman_emotion', 'neutral|intense|mystical|awakening', 'neutral');

return {
  tool: 'unreal_story',
  narrative: narrative,
  vfx: vfxType,
  emotion: metahumanEmotion,
  paths: { character: '/Game/Characters/Naset', vfx: '/Game/VFX/Naset' },
  assetNames: { metahuman: 'MH_NasetOFM_v2', auraVFX: 'NS_NasetOrSacre', oudjatVFX: 'NS_NasetOudjat' },
  instruction: `Crée un script Python pour Unreal Engine 5 qui met en scène l'histoire : ${narrative}. Applique l'effet VFX ${vfxType} et l'expression ${metahumanEmotion} sur le MetaHuman. Utilise le sequencer pour les plans.`
};

const storyArc = $fromAI('story_arc', 'arc narratif complet');
const transitions = $fromAI('transitions', 'dissolve|crossfade|hard_cut', 'dissolve');
const colorMood = $fromAI('color_mood', 'golden_hour|dawn|mystical', 'golden_hour');

return {
  tool: 'premiere_story',
  story: storyArc,
  transition: transitions,
  colorGrade: {
    temperature: 180,
    tint: -3,
    saturation: 108,
    exposure: 0.1,
    contrast: 12
  },
  instruction: `Génère un script .jsx pour Premiere Pro qui monte le court-métrage selon l'histoire : ${storyArc}. Utilise des transitions ${transitions} et un étalonnage ${colorMood}.`
};
